#!/usr/bin/env bash
# F5 replay (control room): the reader's Lean tests in ws-D — build, axioms, export of the 70 named theorems, nanoda, con-leche
set -uo pipefail
R=/results U=tester H=/home/tester W=$H/ws-D CI=$H/ci-tools T=$H/tools E=$H/exports-F5
NT=$(nproc); UPATH="$H/.elan/bin:/usr/local/bin:/usr/bin:/bin"
log() { echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) $*" | tee -a $R/_phase.log; }
step() { local n=$1 to=$2 dir=$3; shift 3; log "$n running"; date +%s > $R/$n.start
  runuser -u $U -- env -i HOME=$H PATH="$UPATH" LEAN_ABORT_ON_PANIC=1 bash -c 'cd "$1" && shift && ulimit -s unlimited 2>/dev/null; exec /usr/bin/time -v timeout "$0" "$@"' "$to" "$dir" "$@" > $R/$n.out 2> $R/$n.err
  echo $? > $R/$n.exit; date +%s > $R/$n.end; log "$n exit $(cat $R/$n.exit) after $(( $(cat $R/$n.end) - $(cat $R/$n.start) )) s"; }
LEX=$CI/lean4export/.lake/build/bin/lean4export; ND2=$T/nanoda_lib/target/release/nanoda_bin; CL=$(ls $T/con-leche/.lake/build/bin/con-leche)
mkdir -p $E && chown $U:$U $E
( cd $W && sha256sum CertMachine/ReaderTests.lean CertMachine/ReaderLiteral.lean CertMachine/ReaderTestsAxioms.lean Statement.lean Solution.lean Challenge.lean ) > $R/F5.files.sha256
grep -nE 'sorry|native_decide|implemented_by|@\[extern|^[[:space:]]*axiom[[:space:]]' $W/CertMachine/ReaderTests.lean $W/CertMachine/ReaderLiteral.lean > $R/F5.grep.txt; log "F5 grep: $(wc -l < $R/F5.grep.txt) lines"
step F5B 3600 $W lake build CertMachine.ReaderTests CertMachine.ReaderLiteral
step F5A 3600 $W lake env lean CertMachine/ReaderTestsAxioms.lean
log "F5 axioms: $(grep -c 'depends on axioms' $R/F5A.out) theorems; outside the three: $(grep 'depends on axioms' $R/F5A.out | grep -vE '\[(propext|Classical.choice|Quot.sound)(, (propext|Classical.choice|Quot.sound))*\]' | wc -l)"
step F5EXP 7200 $W bash -c "lake env $LEX CertMachine.ReaderTests -- CertMachine.ReaderTests.T21_VP CertMachine.ReaderTests.T21_VNP CertMachine.ReaderTests.T21_VPBar CertMachine.ReaderTests.T21_hc CertMachine.ReaderTests.T21_perm CertMachine.ReaderTests.T21_Computes CertMachine.ReaderTests.T21_Approximates CertMachine.ReaderTests.T21_ofNc_toNc CertMachine.ReaderTests.T21_VP CertMachine.ReaderTests.T21_VNP CertMachine.ReaderTests.T21_VPBar CertMachine.ReaderTests.T21_permanent_over_real CertMachine.ReaderTests.T19 CertMachine.ReaderTests.T14a CertMachine.ReaderTests.T14b CertMachine.ReaderTests.T6a CertMachine.ReaderTests.T6b CertMachine.ReaderTests.T6_value CertMachine.ReaderTests.T6_planted_refuted CertMachine.ReaderTests.T7_zero CertMachine.ReaderTests.T7_one CertMachine.ReaderTests.T7m CertMachine.ReaderTests.T5 CertMachine.ReaderTests.T8 CertMachine.ReaderTests.T10 CertMachine.ReaderTests.computes_mono CertMachine.ReaderTests.approximates_mono CertMachine.ReaderTests.pow_add_self_mono CertMachine.ReaderTests.T13 CertMachine.ReaderTests.totalDegree_aeval_le CertMachine.ReaderTests.T16a CertMachine.ReaderTests.T16 CertMachine.ReaderTests.shift_bound CertMachine.ReaderTests.poly_bound CertMachine.ReaderTests.T17 CertMachine.ReaderTests.finRotate_isCycleOn CertMachine.ReaderTests.eval_hc_univ CertMachine.ReaderTests.eval_hc_miss CertMachine.ReaderTests.hc_ne_C CertMachine.ReaderTests.hc_ne_X CertMachine.ReaderTests.T11b CertMachine.ReaderTests.computes_map CertMachine.ReaderTests.T18i CertMachine.ReaderTests.map_perm CertMachine.ReaderTests.map_hc CertMachine.ReaderTests.T9a CertMachine.ReaderTests.T9b CertMachine.ReaderTests.T9c CertMachine.ReaderTests.T20a CertMachine.ReaderTests.T20b CertMachine.ReaderTests.T20c CertMachine.ReaderTests.T15 CertMachine.ReaderTests.T18ii CertMachine.ReaderTests.rename_symm_rename CertMachine.ReaderTests.vp_rename CertMachine.ReaderTests.vp_of_rename CertMachine.ReaderTests.T23_VP CertMachine.ReaderTests.rename_aeval_bits CertMachine.ReaderTests.vnp_rename CertMachine.ReaderTests.renameFamily_symm CertMachine.ReaderTests.T23_VNP CertMachine.ReaderTests.approximates_rename CertMachine.ReaderTests.vpbar_rename CertMachine.ReaderTests.T23_VPBar CertMachine.ReaderTests.T23_fin CertMachine.ReaderTests.T4b CertMachine.ReaderTests.inGate_step CertMachine.ReaderTests.inGate_eq CertMachine.ReaderTests.T4a CertMachine.ReaderTests.T4c  > $E/readertests.ndjson"
sed "s#\"export_file_path\": \"[^\"]*\"#\"export_file_path\": \"$E/readertests.ndjson\"#" $H/exports/nanoda.json > $E/nanoda.json; chown $U:$U $E/nanoda.json
step F5ND 14400 $E $ND2 $E/nanoda.json
step F5CL 14400 $E $CL --jobs=$NT $E/readertests.ndjson
sha256sum $E/*.ndjson > $R/F5.exports.sha256
log "F5 DONE: B=$(cat $R/F5B.exit) A=$(cat $R/F5A.exit) ND=$(cat $R/F5ND.exit) CL=$(cat $R/F5CL.exit)"
